root="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
def path(mod):
    return os.path.join(root, mod.replace('.','/')+".lean")
seen=set()
stack=["AlgebraicJacobian.Picard.Pic0SigmaSheaf"]
missing=[]
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    p=path(m)
    if not os.path.exists(p):
        if m.startswith("AlgebraicJacobian"): missing.append(m)
        continue
    for line in open(p):
        mm=re.match(r'^import\s+(\S+)',line)
        if mm and mm.group(1).startswith("AlgebraicJacobian"):
            stack.append(mm.group(1))
proj=[m for m in seen if m.startswith("AlgebraicJacobian")]
print("project files in cone:",len(proj))
print("missing modules:",missing)
bad={}
for m in sorted(proj):
    p=path(m)
    if not os.path.exists(p): continue
    hits=[]
    for i,line in enumerate(open(p),1):
        if re.search(r'\bsorry\b|\badmit\b|^\s*axiom\s|sorryAx|native_decide', line):
            hits.append((i,line.rstrip()[:150]))
    if hits: bad[m]=hits
print("=== files with sorry/axiom/admit ===")
for m,h in bad.items():
    print(m)
    for i,l in h: print("   ",i,l)
if not bad: print("NONE")
open("/tmp/cone_ajcr.txt","w").write("\n".join(sorted(proj)))
